import Link from"next/link";import{notFound}from"next/navigation";import{getCurrentUser}from"@/lib/auth/session";import{getChallengeDetail}from"@/lib/challenges/queries";import{CHALLENGE_POLICY}from"@/lib/challenges/policy";import type{ChallengeType}from"@/lib/gamification/catalog";import{startChallenge}from"../actions";
export default async function Page({params,searchParams}:{params:Promise<{challengeId:string}>;searchParams:Promise<{error?:string}>}){const[{challengeId},q,u]=await Promise.all([params,searchParams,getCurrentUser()]);const d=await getChallengeDetail(challengeId,u?.id);if(!d)notFound();const type=d.challenge.type as ChallengeType;const title=d.challenge.titleVi;const own=d.own;return <main className="min-h-screen bg-slate-50 px-4 py-8"><div className="mx-auto max-w-4xl"><Link href="/ranking">← Xếp hạng</Link><h1 className="mt-5 text-3xl font-black">{title}</h1><p className="mt-2">{type.replaceAll("_"," ")} · {CHALLENGE_POLICY[type].durationMs/60_000} phút · Trạng thái: <strong>{d.phase}</strong></p>{q.error&&<p className="mt-4 rounded-xl bg-amber-50 p-4" role="alert">Không thể bắt đầu lúc này. Cửa sổ làm bài có thể đã đóng.</p>}{!u?<Link className="mt-6 inline-flex rounded-xl bg-slate-900 p-4 font-bold text-white" href="/sign-in">Đăng nhập để tham gia</Link>:own?<Link className="mt-6 inline-flex rounded-xl bg-teal-700 p-4 font-bold text-white" href={own.status==="COMPLETED"?`/ranking/challenges/run/${own.id}/result`:`/ranking/challenges/run/${own.id}`}>{own.status==="COMPLETED"?"Xem kết quả":"Tiếp tục lượt xếp hạng"}</Link>:d.phase==="LIVE"?<section className="mt-6 rounded-2xl border-2 border-amber-300 bg-white p-6"><p className="font-bold">Bạn chỉ có 1 lượt xếp hạng cho thử thách này. Khi bắt đầu, lượt này sẽ được ghi nhận.</p><p className="mt-2 text-sm">You have one ranked attempt. Starting commits this attempt.</p><form action={startChallenge.bind(null,challengeId)}><button className="mt-4 min-h-12 rounded-xl bg-slate-900 px-6 font-bold text-white">Bắt đầu</button></form></section>:null}<section className="mt-10"><h2 className="text-2xl font-black">Bảng xếp hạng · {d.participants} người</h2><ol className="mt-4 grid gap-2">{d.leaderboard.map(r=><li className="grid grid-cols-[4rem_1fr_auto] rounded-xl bg-white p-4" key={r.runId}><strong>#{r.rank}</strong><span>{r.visibility==="PUBLIC"?r.name:"Người học ẩn danh"}</span><strong>{r.score}/{type==="FULL_200"?200:100}</strong></li>)}</ol></section></div></main>}
